        <th width="33%" class="text-center" style="border-right: 1px solid #000; background-color: #e9ecef; padding: 4px 6px; font-size: 12px;">Bill To</th>
        <th width="33%" class="text-center" style="border-right: 1px solid #000; background-color: #e9ecef; padding: 4px 6px; font-size: 12px;">Invoice Details</th>
