            <td style="border-right: 1px solid #000; padding: 3px 6px; text-align: center;">{{ tax.rate or "-" }}{% if tax.rate %}%{% endif %}</td>
            <td style="border-right: 1px solid #000; padding: 3px 6px; text-align: right;">{{ doc.get_formatted("net_total") or doc.get_formatted("total") }}</td>
            <td style="padding: 3px 6px; text-align: right; font-weight: 600;">{{ tax.get_formatted("tax_amount") }}</td>
        </tr>
        {% endif %}
        {% endfor %}
    </tbody>
</table>
