css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap');

.print-format,
.print-format *,
.print-format table,
.print-format tr,
.print-format th,
.print-format td,
.print-format p,
.print-format span,
.print-format div,
.print-format h1,
.print-format h2,
.print-format h3,
.print-format h4,
.print-format h5,
.print-format h6,
.print-format .label,
.print-format .value,
.print-format .tax-break-up,
.print-format .tax-break-up * {
    font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif !important;
}

