</table>", "custom": 1}]}]}, {"label": "", "margin": {"top": 4, "right": 0, "bottom": 0, "left": 0}, "columns": [{"label": "", "fields": [{"label": "Custom HTML", "fieldname": "custom_html_3", "fieldtype": "HTML", "html": "{% set company_doc = frappe.get_doc("Company", doc.company) if doc.company else None %}
