<div class="bank-details-wrapper" style="font-size: 11.5px; line-height: 1.35; padding: 2px 0;">
    <table style="border: 0; width: 100%; border-collapse: collapse; margin: 0;">
        <tr>
            {% if doc.outstanding_amount != 0 and upi_id.value != "" %}
                <td style="border: 0; padding: 0 10px 0 0; width: 75px; vertical-align: top;">
                    <div class="payment_qr">
                        {% set upi_qr_text = "upi://pay?pa=" ~ upi_id.value ~ "&tn=" ~ doc.name ~ "&cu=INR" %}
                        {% if doc.outstanding_amount < 100000 %}
                            {% set upi_qr_text = upi_qr_text ~ "&am=" ~ doc.outstanding_amount %}
                        {% endif %}
                        {{ web_block("UPI QR Code", values={"upi_qr_text": upi_qr_text}) }}
