    <tr>
        <td style="padding: 2px 0; text-align: left; font-weight: 600; color: #444;">Net Total:</td>
        <td style="padding: 2px 0; text-align: right; font-weight: 600; color: #000;">{{ doc.get_formatted("total") or doc.get_formatted("net_total") }}</td>
