<table class="table table-condensed" style="table-layout:fixed; width: 100%; border: 1px solid #000; font-size: 11px; margin-top: 6px;">
    <thead>
        <tr style="border-bottom: 1px solid #000; background-color: #e9ecef; text-align: center;">
            <th style="border-right: 1px solid #000; padding: 3px 6px; font-size: 11px;">Tax Description</th>
            <th style="border-right: 1px solid #000; padding: 3px 6px; font-size: 11px;">Rate</th>
            <th style="border-right: 1px solid #000; padding: 3px 6px; font-size: 11px;">Taxable Amount</th>
