css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap');

.print-format,
.print-format *,
.print-format table,
.print-format tr,
.print-format th,
.print-format td,
.print-format p,
.print-format span,
.print-format div,
.print-format h1,
.print-format h2,
.print-format h3,
.print-format h4,
.print-format h5,
.print-format h6,
.print-format .label,
.print-format .value,
.print-format .tax-break-up,
.print-format .tax-break-up * {
    font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif !important;
}

.print-format {
    font-size: 12px !important;
    line-height: 1.35 !important;
    color: #000 !important;
    padding: 0 !important;
}

.print-format p {
    margin: 0 0 2px 0 !important;
    font-size: 11.5px !important;
}

.print-format table {
    width: 100% !important;
    font-size: 11.5px !important;
    line-height: 1.35 !important;
    border-collapse: collapse !important;
}

.print-format th {
    font-size: 12px !important;
    font-weight: 700 !important;
    padding: 4px 6px !important;
    background-color: #e9ecef !important;
    color: #000 !important;
}

.print-format td {
    font-size: 11.5px !important;
    padding: 4px 6px !important;
    vertical-align: top !important;
}

.bank-details-wrapper,
.bank-details-wrapper table,
.bank-details-wrapper td {
    line-height: 1.35 !important;
    font-size: 11.5px !important;
}

.bank-details-wrapper p {
    margin: 0 0 2px 0 !important;
    line-height: 1.35 !important;
    font-size: 11.5px !important;
}

.invoice-footer,
.invoice-footer * {
    font-size: 10.5px !important;
    line-height: 1.3 !important;
}

.invoice-footer {
    width: 100% !important;
    margin-top: auto !important;
    padding-top: 5px !important;
}

@media screen {
    .print-format {
        display: flex !important;
        flex-direction: column !important;
        min-height: 280mm !important;
        box-sizing: border-box !important;
    }
}

@media print {
    @page {
        size: A4;
        margin: 6mm 8mm;
    }
    .print-format {
        margin: 0 !important;
        padding: 0 !important;
        min-height: 275mm !important;
        display: flex !important;
        flex-direction: column !important;
    }
}

