{"header": null, "footer": "{% set first_name = frappe.db.get_value("User", doc.owner, "first_name") if doc.owner else "" %}
{% set last_name = frappe.db.get_value("User", doc.owner, "last_name") if doc.owner else "" %}
{% set generated_by = (first_name ~ " " ~ (last_name or "")).strip() or doc.owner %}
{% set generated_on = doc.get_formatted("creation") %}

<div class="invoice-footer" style="width: 100%; border-top: 1px solid #000; padding-top: 4px; font-size: 10.5px; color: #222;">
    <table style="width: 100%; border: 0; border-collapse: collapse; margin: 0;">
        <tr>
            <td style="border: 0; padding: 0; text-align: left; vertical-align: middle; width: 50%; font-size: 10.5px;">
                <b>Generated By:</b> {{ generated_by }} &nbsp;|&nbsp; <b>Generated On:</b> {{ generated_on }}
            </td>
            <td style="border: 0; padding: 0; text-align: right; vertical-align: middle; width: 50%; font-size: 10.5px; font-style: italic; color: #333;">
                This is a computer-generated invoice copy and no signature is required.
            </td>
        </tr>
    </table>
</div>", "sections": [{"label": "", "margin": {"top": 0, "right": 0, "bottom": 0, "left": 0}, "columns": [{"label": "", "fields": [{"label": "Custom HTML", "fieldname": "custom_html_1", "fieldtype": "HTML", "html": "<!-- Top Header Box -->
<table class="table table-condensed" style="table-layout:fixed; width: 100%; border: 1px solid #000; border-collapse: collapse; font-size: 11.5px; margin: 0 0 6px 0;">
    <tr>
        <td width="30%" style="border: 0; text-align: center; vertical-align: middle; padding: 6px 8px;">
            {% set website_logo = frappe.db.get_single_value("Website Settings", "app_logo") %}
            {% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") if doc.company else None %}
            {% set logo_url = website_logo or company_logo %}
            {% if logo_url %}
                <img src="{{ logo_url }}" style="max-width: 95%; max-height: 48px; object-fit: contain; margin: 0 auto 3px auto; display: block;">
            {% endif %}
            <h3 style="margin: 2px 0 0 0; font-size: 15px; font-weight: 800; text-transform: uppercase; text-align: center;">
                <b>{{ doc.select_print_heading if doc.select_print_heading else ("Credit Note" if doc.is_return else "Tax Invoice") }}</b>
            </h3>
        </td>
        <td width="34%" style="border: 0; text-align: center; vertical-align: middle; padding: 6px;">
            <div style="display: inline-block; border: 1.5px solid #000; background-color: #f1f3f5; padding: 5px 12px; border-radius: 4px;">
                <span style="font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.4px;">
                    Duplicate for Transporter
                </span>
            </div>
        </td>
        <td width="36%" style="border: 0; text-align: right; vertical-align: middle; padding: 6px 8px; line-height: 1.35; font-size: 11.5px;">
            <b style="font-size: 13px;">{{ doc.company }}</b><br>
            {% if doc.company_address_display %}
                {% set raw_addr = doc.company_address_display.replace('\n', ' ').split('<br>') %}
                {% set filtered_lines = [] %}
                {% for l in raw_addr %}
                    {% set l_clean = l.strip() %}
                    {% if l_clean and not l_clean.startswith("GSTIN") and not l_clean.startswith("India") %}
                        {% set _ = filtered_lines.append(l_clean) %}
                    {% endif %}
                {% endfor %}
                {{ filtered_lines | join(", ") }}<br>
            {% endif %}
            {% set comp_phone = frappe.db.get_value("Company", doc.company, "phone_no") if doc.company else None %}
            <b>GSTIN:</b> {{ doc.company_tax_id or doc.company_gstin }}{% if comp_phone %} | <b>Phone:</b> {{ comp_phone }}{% endif %}<br>
            <b>Place of Supply:</b> {{ doc.place_of_supply }}
        </td>
    </tr>
</table>

<!-- Note Box -->
<table style="table-layout:fixed; width: 100%; border: 1px solid #000; font-size: 11px; margin: 0 0 6px 0;">
    <tr>
        <td width="100%" style="padding: 4px 8px; background-color: #fff;">
            <p style="margin: 0; line-height: 1.35; font-size: 11px;"><b>Note: Customers are requested to do NEFT/RTGS/UPI payment directly to the Company Bank Account. "{{ doc.company }}" is not responsible for payments made by Customers to intermediaries like employees, sales agents, etc.</b></p>
        </td>
    </tr>
</table>

<!-- 3-Column Bill To / Details / Payment Table -->
<table class="table table-condensed" style="table-layout:fixed; width: 100%; border: 1px solid #000; font-size: 11.5px; margin: 0 0 8px 0;">
    <tr style="border-bottom: 1px solid #000; text-align: center;">
